import OrbitingCircles from "./ui/orbiting-circles";

interface Props {
  children: any;
}

export function OrbitingCirclesDemo({ children }: Props) {
  const minRadius = 150;
  const midRadius = 200;
  const maxRadius = 250;

  return (
    <div className="relative md:flex h-[80vh] w-full flex-col items-center justify-center  rounded-lg hidden ">
      <span className="pointer-events-none whitespace-pre-wrap flex justify-center items-center pb-14 pr-4 ">
        {children}
      </span>

      {/* Inner Circles - Basic Technologies (Languages) */}
      <OrbitingCircles
        className="size-[30px] border-none bg-transparent"
        duration={20}
        delay={0}
        radius={minRadius}
      >
        <Icons.python />
      </OrbitingCircles>

      <OrbitingCircles
        className="size-[30px] border-none bg-transparent"
        duration={20}
        delay={5}
        radius={minRadius}
      >
        <Icons.javascript />
      </OrbitingCircles>

      <OrbitingCircles
        className="size-[30px] border-none bg-transparent"
        duration={20}
        delay={10}
        radius={minRadius}
      >
        <Icons.typescript />
      </OrbitingCircles>

      <OrbitingCircles
        className="size-[30px] border-none bg-transparent"
        duration={20}
        delay={15}
        radius={minRadius}
      >
        <Icons.docker />
      </OrbitingCircles>

      {/* Middle Circles - Backend and Servers */}
      <OrbitingCircles
        className="size-[40px] border-none bg-transparent"
        duration={20}
        delay={0}
        radius={midRadius}
      >
        <Icons.nestJs />
      </OrbitingCircles>

      <OrbitingCircles
        className="size-[40px] border-none bg-transparent"
        duration={20}
        delay={7}
        radius={midRadius}
      >
        <Icons.fastapi />
      </OrbitingCircles>

      <OrbitingCircles
        className="size-[40px] border-none bg-transparent"
        duration={20}
        delay={14}
        radius={midRadius}
      >
        <Icons.gitHub />
      </OrbitingCircles>

      {/* Outer Circles (reverse) - Frontend */}
      <OrbitingCircles
        className="size-[50px] border-none bg-transparent"
        radius={maxRadius}
        duration={20}
        reverse
      >
        <Icons.reactJs />
      </OrbitingCircles>
      <OrbitingCircles
        className="size-[50px] border-none bg-transparent"
        radius={maxRadius}
        duration={20}
        delay={3}
        reverse
      >
        <Icons.nextJs />
      </OrbitingCircles>

      <OrbitingCircles
        className="size-[50px] border-none bg-transparent"
        radius={maxRadius}
        duration={20}
        delay={6}
        reverse
      >
        <Icons.astro />
      </OrbitingCircles>

      <OrbitingCircles
        className="size-[50px] border-none bg-transparent"
        radius={maxRadius}
        duration={20}
        delay={20}
        reverse
      >
        <Icons.angular />
      </OrbitingCircles>

      <OrbitingCircles
        className="size-[50px] border-none bg-transparent"
        radius={maxRadius}
        duration={20}
        delay={12}
        reverse
      >
        <Icons.tailwind />
      </OrbitingCircles>

      <OrbitingCircles
        className="size-[50px] border-none bg-transparent"
        radius={maxRadius}
        duration={20}
        delay={15}
        reverse
      >
        <Icons.expo />
      </OrbitingCircles>
    </div>
  );
}

